'use client'

import { Button } from '@/shared/Button'
import { useNavigate } from '@tanstack/react-router'
import { Clock, Crown } from 'lucide-react'
import { FC } from 'react'

// --- Static data hoisted outside the component ---

const ICON_CLASS = 'w-4 h-4 xl:w-5 xl:h-5'

const linksFr = new Map([
  ['1h', 'trending-lasthours'],
  ['6h', 'trending-6hours'],
  ['24h', 'trending'],
  ['7 days', 'trending-7days'],
  ['30 days', 'trending-30days'],
])

const linksAr = new Map([
  ['1 ساعة', 'trending-lasthours'],
  ['6 ساعات', 'trending-6hours'],
  ['24 ساعة', 'trending'],
  ['7 أيام', 'trending-7days'],
  ['30 يومًا', 'trending-30days'],
])

const tabsFr = Array.from(linksFr.keys())
const tabsAr = Array.from(linksAr.keys())

// --- Tab button helper to eliminate active/inactive duplication ---

const TabButton: FC<{
  isActive: boolean
  onClick: () => void
  icon?: React.ReactNode
  children: React.ReactNode
}> = ({ isActive, onClick, icon, children }) => (
  <Button
    {...(isActive ? { color: 'lime' as const } : { outline: true as const })}
    onClick={onClick}
    className="cursor-pointer"
  >
    {icon}
    {children}
  </Button>
)

// --- Main component ---

interface Props {
  tabActive: {
    fr: string
    ar: string
  }
  onChangeTab?: (item: string) => void
  isFr?: boolean
}

const SectionTabHeader: FC<Props> = ({ tabActive, onChangeTab, isFr }) => {
  const navigate = useNavigate()
  const links = isFr ? linksFr : linksAr
  const tabs = isFr ? tabsFr : tabsAr
  const activeKey = isFr ? 'fr' : 'ar'

  const handleClickTab = (tab: string) => {
    if (tab === 'last') {
      navigate({
        to: isFr ? '/news/fr/$postId' : '/news/$postId',
        params: { postId: isFr ? 'dernieres-actualites' : 'آخر-الأخبار' },
      })
      return
    }

    if (tab === 'top') {
      navigate({
        to: isFr ? '/news/fr/top-news' : '/news/top-news',
        search: { page: 1 },
      })
      return
    }

    navigate({
      to: isFr ? '/news/fr/$postId' : '/news/$postId',
      params: { postId: links.get(tab) || 'trending' },
    })
    onChangeTab?.(tab)
  }

  return (
    <div className="section-tab-header relative mb-2 flex flex-col">
      <div className="flex grow flex-wrap gap-2">
        <TabButton
          isActive={tabActive.fr === 'top'}
          onClick={() => handleClickTab('top')}
          icon={<Crown className={`${ICON_CLASS} text-amber-400`} />}
        >
          {isFr ? 'Top News' : 'أهم الأخبار'}
        </TabButton>

        <TabButton
          isActive={tabActive.fr === 'last'}
          onClick={() => handleClickTab('last')}
          icon={<Clock className={`${ICON_CLASS} text-fuchsia-500`} />}
        >
          {isFr ? 'Dernières News' : 'آخر الأخبار'}
        </TabButton>

        {tabs.map((tab) => (
          <TabButton
            key={tab}
            isActive={tabActive[activeKey] === tab}
            onClick={() => handleClickTab(tab)}
          >
            {tab}
          </TabButton>
        ))}
      </div>
    </div>
  )
}

export default SectionTabHeader
